// FAP §9 result envelope. Mirrors the inbound requestId so transport.ts can
// resolve the matching submit() promise. data.serverTs lets the smoke test
// measure roundtrip latency.
const env = msg.payload || {};
const result = {
    type: 'result',
    ok: true,
    action: 'ping',
    requestId: env.requestId,
    sessionId: env.sessionId,
    data: { pong: true, serverTs: Date.now() }
};
msg.payload = result;
// Preserve _socketId so merge-session-send routes to the requesting client.
return msg;
